-- Real province boundaries (GISTDA L05_Province_GISTDA_50k, simplified 0.002°) — dev seed, loaded after seed.sql.
-- Generated from etl/.raw/gistda_admin (D-028). Real ETL (`etl/run.py --source gistda`) swaps full-resolution data over this.
delete from ref.admin_boundaries where level = 'province';

-- Coverage for ALL 77 provinces (D-029): every province enabled.
--   salinity_origin : northeast → inland_rock_salt · 23 sea-coast provinces (Gulf of Thailand + Andaman,
--                     DOPA codes verified against ref.admin_boundaries names) → coastal_intrusion · else none
--   default_variety : ASSUMPTION (D-029, review with Rice Department) — northeast KDML105, north RD6
--                     (glutinous), central/east/west/south RD41
--   has_dgr         : DGR 1:100k per-province file exists on data.go.th (DATA_SOURCES §3) — no file for
--                     50 51 52 53 54 55 56 57 58 84 85 90 91 95, Phetchabun 67 listed without URL → 62 provinces
-- Upsert so it also overrides the 3 synthetic rows from seed.sql (44 / 40 / 72).
select b.code, true,
       case when b.region = 'northeast' then 'inland_rock_salt'
            when b.code in ('10','11','74','75','24','20','21','22','23','76','77',          -- Gulf: upper + east + west
                            '86','84','80','90','94','96',                                   -- Gulf: south
                            '85','82','83','81','92','91') then 'coastal_intrusion'          -- Andaman
            else 'none' end,
       case b.region when 'northeast' then 'KDML105' when 'north' then 'RD6' else 'RD41' end,  -- ASSUMPTION
       false, false,
       b.code not in ('50','51','52','53','54','55','56','57','58','67','84','85','90','91','95'),
       case when b.code = '44' then 'Phase 1 pilot · LDD placeholder'
            else 'nationwide (D-029) · LDD placeholder' end
from ref.admin_boundaries b
where b.level = 'province'
on conflict (province_code) do update
  set enabled = excluded.enabled, salinity_origin = excluded.salinity_origin,
      default_variety = excluded.default_variety, has_dgr = excluded.has_dgr, note = excluded.note;
